func addCmd() *cobra.Command {
	var templates []string
	var newBranch string
	var base string
	var open bool
	var force bool
	var useTmux bool

	cmd := &cobra.Command{
		Use:   "add <feature>",
		Short: "Create a feature workspace",
		Long: `Create a feature workspace with an inject/ directory for shared files.

Files in inject/ are symlinked into every worktree. Use -n to also
create a first worktree branch, and --open to launch the agent.

Note: injected files appear as untracked in git status. Add them to
.gitignore or place them in an already-ignored subfolder.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return addCheckout(ws, feature, templates, newBranch, base, force, open, useTmux)
			}
			return addExternal(feature, templates, newBranch, base, force, open, useTmux)
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Template directory to copy into inject/ (can be specified multiple times)")
	cmd.Flags().StringVarP(&newBranch, "new", "n", "", "Also create a worktree branch")
	cmd.Flags().StringVar(&base, "base", "", "Base branch for the new worktree (default: repo's default branch)")
	cmd.Flags().BoolVar(&open, "open", false, "Open the worktree after creation (used with -n)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Open in tmux session (used with --open)")

	return cmd
}

// addExternal preserves existing external-mode add semantics.
func addExternal(feature string, templates []string, newBranch, base string, force, open, useTmux bool) error {
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	root := internal.FeaturePath(feature)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Join(root, "worktrees"), 0755); err != nil {
		return fmt.Errorf("creating worktrees directory: %w", err)
	}
	if err := os.WriteFile(filepath.Join(root, "FEATURE.md"), []byte("# "+feature+"\n"), 0644); err != nil {
		return fmt.Errorf("creating FEATURE.md: %w", err)
	}

	injectDir := internal.InjectPath(root)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}

	applyTemplates(injectDir, templates)

	claudeLocal := filepath.Join(injectDir, "CLAUDE.local.md")
	if _, err := os.Stat(claudeLocal); os.IsNotExist(err) {
		if err := os.WriteFile(claudeLocal, []byte("# "+feature+" - shared context\n\nThis file is symlinked into every worktree for this feature.\nEdit it in the workspace inject/ directory.\n"), 0644); err != nil {
			return fmt.Errorf("creating CLAUDE.local.md: %w", err)
		}
	}

	orchPath := filepath.Join(root, ".claude", "skills", "tesseraworkspaces-orchestrator", "SKILL.md")
	installFile(orchPath, skills.ClaudeOrchestratorSkill, false)

	fmt.Println("Feature added:", feature)

	if newBranch != "" {
		if err := createWorktree(feature, newBranch, base, "", force); err != nil {
			return err
		}
		if open {
			path := internal.WorktreePath(feature, newBranch)
			if useTmux {
				openWithTmux(feature, newBranch, path)
			} else {
				openDirect(path)
			}
		}
	}
	return nil
}

// addCheckout creates durable feature assets under .tws/features/<feature>
// for checkout mode. Idempotent: re-running on an existing feature updates
// only missing assets.
func addCheckout(ws internal.Workspace, feature string, templates []string, newBranch, base string, force, open, useTmux bool) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	root := ws.FeaturePath(feature)

	// Create the feature directory (no worktrees/ subdirectory in checkout mode).
	if err := os.MkdirAll(root, 0755); err != nil {
		return fmt.Errorf("creating feature directory: %w", err)
	}

	// FEATURE.md
	featureMD := filepath.Join(root, "FEATURE.md")
	if _, err := os.Stat(featureMD); os.IsNotExist(err) {
		if err := os.WriteFile(featureMD, []byte("# "+feature+"\n"), 0644); err != nil {
			return fmt.Errorf("creating FEATURE.md: %w", err)
		}
	}

	// inject/ directory
	injectDir := internal.InjectPath(root)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}

	applyTemplates(injectDir, templates)

	// Default CLAUDE.local.md if no template provided one
	claudeLocal := filepath.Join(injectDir, "CLAUDE.local.md")
	if _, err := os.Stat(claudeLocal); os.IsNotExist(err) {
		if err := os.WriteFile(claudeLocal, []byte("# "+feature+" - shared context\n\nThis file is maintained in the checkout workspace.\n"), 0644); err != nil {
			return fmt.Errorf("creating CLAUDE.local.md: %w", err)
		}
	}

	// Orchestrator skill in feature .claude/skills/
	orchPath := filepath.Join(root, ".claude", "skills", "tesseraworkspaces-orchestrator", "SKILL.md")
	installFile(orchPath, skills.ClaudeOrchestratorSkill, false)

	fmt.Println("Feature added:", feature)

	// In checkout mode, -n creates a branch (not a worktree).
	if newBranch != "" {
		if err := createCheckoutBranch(ws, feature, newBranch, base, force); err != nil {
			return err
		}
		if open {
			// In checkout mode, "open" switches to branch in the repo root.
			if useTmux {
				openCheckoutTmux(ws, feature, newBranch)
			} else {
				fmt.Printf("Branch %s created. Use 'git checkout %s' to switch.\n", newBranch, newBranch)
			}
		}
	}
	return nil
}

// applyTemplates copies files from the configured template dir and any
// explicit --template dirs into the inject directory.
func applyTemplates(injectDir string, extraTemplates []string) {
	// Configured default template first
	defaultTemplate := internal.TemplatePath()
	if defaultTemplate != "" {
		count, err := copyDir(defaultTemplate, injectDir)
		if err != nil {
			fmt.Printf("Warning: default template copy failed: %v\n", err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from default template\n", count)
		}
	}

	// Then explicit --template dirs (layered in order)
	for _, tmplDir := range extraTemplates {
		info, err := os.Stat(tmplDir)
		if err != nil || !info.IsDir() {
			fmt.Printf("Warning: template directory not found: %s\n", tmplDir)
			continue
		}
		count, err := copyDir(tmplDir, injectDir)
		if err != nil {
			fmt.Printf("Warning: template copy failed for %s: %v\n", tmplDir, err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from %s\n", count, tmplDir)
		}
	}
}

// copyDir copies all files from src to dst, preserving directory structure.
// Does not overwrite existing files. Returns the count of files copied.
func copyDir(src, dst string) (int, error) {
	count := 0
	err := filepath.Walk(src, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(src, srcPath)
		if err != nil {
			return err
		}
		if relPath == "." {
			return nil
		}

		dstPath := filepath.Join(dst, relPath)

		if info.IsDir() {
			return os.MkdirAll(dstPath, 0755)
		}

		// Skip if exists (conflict resolution is a separate feature)
		if _, err := os.Stat(dstPath); err == nil {
			fmt.Printf("  skip: %s (exists)\n", relPath)
			return nil
		}

		// Copy file
		in, err := os.Open(srcPath)
		if err != nil {
			return err
		}
		defer in.Close() //nolint:errcheck

		out, err := os.Create(dstPath)
		if err != nil {
			return err
		}
		defer out.Close() //nolint:errcheck

		if _, err := io.Copy(out, in); err != nil {
			return err
		}
		count++
		return nil
	})
	return count, err
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func archiveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "archive <feature> <branch>",
		Short: "Remove worktree from disk, keep branch and metadata",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]
			branch := args[1]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return archiveCheckout(ws, feature, branch)
			}
			return archiveExternal(feature, branch)
		},
	}
}

// archiveCheckout marks a branch as archived in metadata only.
// The git branch is preserved; no worktree to remove.
func archiveCheckout(ws internal.Workspace, feature, branch string) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	found := false
	for i := range stack.Branches {
		if stack.Branches[i].Name == branch {
			if stack.Branches[i].Archived {
				fmt.Printf("Branch %s is already archived\n", branch)
				return nil
			}
			stack.Branches[i].Archived = true
			found = true
			break
		}
	}
	if !found {
		return fmt.Errorf("branch %q not found in stack for feature %s", branch, feature)
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		return fmt.Errorf("error saving stack: %w", err)
	}

	fmt.Printf("Archived branch: %s (git branch preserved)\n", branch)
	return nil
}

// archiveExternal removes the worktree from disk but preserves the git branch.
func archiveExternal(feature, branch string) error {
	if err := internal.GuardFeatureName(internal.TwsRoot(), feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, branch)

	if _, err := os.Stat(path); os.IsNotExist(err) {
		// Mark as archived in stack if not already.
		stack, loadErr := internal.LoadStack(featurePath)
		if loadErr == nil {
			for i := range stack.Branches {
				if stack.Branches[i].Name == branch {
					stack.Branches[i].Archived = true
					break
				}
			}
			_ = internal.SaveStack(featurePath, stack)
		}
		fmt.Printf("Worktree already removed: %s\n", path)
		return nil
	}

	// Use git worktree remove to cleanly detach.
	if err := internal.Run("git", "worktree", "remove", "--force", path); err != nil {
		return fmt.Errorf("error removing worktree: %w", err)
	}

	// Mark as archived in stack.
	stack, loadErr := internal.LoadStack(featurePath)
	if loadErr == nil {
		for i := range stack.Branches {
			if stack.Branches[i].Name == branch {
				stack.Branches[i].Archived = true
				break
			}
		}
		_ = internal.SaveStack(featurePath, stack)
	}

	// Kill tmux session if running.
	session := sanitizeSessionName(feature + "/" + branch)
	if sessionExists(session) {
		_ = internal.RunSilent("tmux", "kill-session", "-t", session)
	}

	fmt.Printf("Archived worktree: %s → %s (branch preserved)\n", feature, branch)
	return nil
}

package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func closeCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "close [feature] [branch]",
		Short: "Close a worktree session (tmux or checkout)",
		Args:  cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			ws, err := internal.RequireWorkspace()
			if err == nil && ws.Mode == internal.ModeCheckout {
				state, loadErr := internal.LoadCheckoutAgentSession(ws)
				if loadErr != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				if len(args) == 0 {
					return []string{state.Feature}, cobra.ShellCompDirectiveNoFileComp
				}
				if len(args) == 1 && args[0] == state.Feature {
					return []string{state.Name}, cobra.ShellCompDirectiveNoFileComp
				}
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		// Deliberately guard-free: the external branch only builds a tmux
		// session name and kills that session — it joins no root and creates,
		// reads, or removes nothing under TwsRoot(). The checkout branch reads
		// the recorded session rather than a caller-supplied name. A registered
		// space therefore cannot be reached through this command.
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			// Checkout mode: delegate to checkout close
			if ws.Mode == internal.ModeCheckout {
				if cerr := runCheckoutClose(ws, args); cerr != nil {
					return cerr
				}
				fmt.Println("Checkout session closed.")
				return nil
			}

			// External mode: requires exactly 2 args
			if len(args) != 2 {
				return fmt.Errorf("usage: tws close <feature> <branch>")
			}

			feature := args[0]
			branch := args[1]

			session := sanitizeSessionName(feature + "/" + branch)

			if !sessionExists(session) {
				return fmt.Errorf("no tmux session found for %s/%s", feature, branch)
			}

			if err := internal.Run("tmux", "kill-session", "-t", session); err != nil {
				return fmt.Errorf("error killing session: %w", err)
			}

			fmt.Printf("Closed tmux session: %s\n", session)
			return nil
		},
	}
}

// TmuxSessionName returns the tmux session name for a feature/branch pair.
func TmuxSessionName(feature, branch string) string {
	return sanitizeSessionName(feature + "/" + branch)
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func deleteCmd() *cobra.Command {
	var deleteBranches bool
	var forceDeleteBranches bool

	cmd := &cobra.Command{
		Use:     "delete <feature>",
		Aliases: []string{"rm"},
		Short:   "Remove feature and all worktrees",
		Args:    cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return deleteCheckout(ws, feature, deleteBranches, forceDeleteBranches)
			}
			return deleteExternal(feature, deleteBranches, forceDeleteBranches)
		},
	}

	cmd.Flags().BoolVar(&deleteBranches, "delete-branches", false, "Also delete git branches (uses safe -d; unmerged branches are skipped)")
	cmd.Flags().BoolVar(&forceDeleteBranches, "force-delete-branches", false, "Force-delete git branches even if unmerged (uses -D)")

	return cmd
}

// deleteCheckout deletes a feature in checkout mode.
// --delete-branches validates all targets before deleting any.
// Refuses to delete the currently checked-out branch.
func deleteCheckout(ws internal.Workspace, feature string, deleteBranches, forceDelete bool) (retErr error) {
	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	// Open the spaces delete transaction before any branch validation or
	// filesystem removal. It refuses a registered space name and any nested
	// registered target, and holds the lock through os.RemoveAll so a
	// concurrent `tws space add` cannot interleave.
	tx, err := internal.BeginSpacesFeatureDelete(ws.MetadataRoot, feature, featurePath)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, tx.Release()) }()

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature not found: %s", feature)
	}

	stack, _ := internal.LoadStack(featurePath)

	if deleteBranches || forceDelete {
		// Determine the current branch to refuse deletion.
		currentBranch := currentGitBranch(ws.RepoRoot)

		backups, err := validateCheckoutBranchDeletion(ws.RepoRoot, stack, currentBranch, forceDelete)
		if err != nil {
			return err
		}
		flag := "-d"
		if forceDelete {
			flag = "-D"
		}
		var deleted []branchBackup
		for _, backup := range backups {
			if err := internal.RunSilentDir(ws.RepoRoot, "git", "branch", flag, backup.name); err != nil {
				rollbackErr := restoreDeletedBranches(ws.RepoRoot, deleted)
				if rollbackErr != nil {
					return fmt.Errorf("failed to delete git branch %q: %w; rollback also failed: %v", backup.name, err, rollbackErr)
				}
				return fmt.Errorf("failed to delete git branch %q: %w; deleted branches restored and feature metadata preserved", backup.name, err)
			}
			deleted = append(deleted, backup)
		}
	}

	// Delete feature metadata.
	if err := os.RemoveAll(featurePath); err != nil {
		return fmt.Errorf("error removing feature directory: %w", err)
	}

	fmt.Printf("Deleted feature: %s\n", feature)
	return nil
}

type branchBackup struct {
	name string
	sha  string
}

func validateCheckoutBranchDeletion(repoRoot string, stack internal.Stack, currentBranch string, force bool) ([]branchBackup, error) {
	backups := make([]branchBackup, 0, len(stack.Branches))
	for _, entry := range stack.Branches {
		branch := entry.GitBranch()
		if branch == currentBranch {
			return nil, fmt.Errorf("cannot delete branch %q: it is the currently checked-out branch; switch to another branch first", branch)
		}
		shaBytes, err := exec.Command("git", "-C", repoRoot, "rev-parse", "--verify", branch+"^{commit}").Output()
		if err != nil {
			return nil, fmt.Errorf("cannot delete branch %q: ref does not resolve", branch)
		}
		if !force && internal.RunSilentDir(repoRoot, "git", "merge-base", "--is-ancestor", branch, "HEAD") != nil {
			return nil, fmt.Errorf("cannot safely delete unmerged branch %q; use --force-delete-branches", branch)
		}
		backups = append(backups, branchBackup{name: branch, sha: strings.TrimSpace(string(shaBytes))})
	}
	return backups, nil
}

func restoreDeletedBranches(repoRoot string, backups []branchBackup) error {
	var failures []string
	for _, backup := range backups {
		if err := internal.RunSilentDir(repoRoot, "git", "branch", backup.name, backup.sha); err != nil {
			failures = append(failures, backup.name)
		}
	}
	if len(failures) > 0 {
		return fmt.Errorf("could not restore branches: %s", strings.Join(failures, ", "))
	}
	return nil
}

// deleteExternal deletes a feature in external mode.
func deleteExternal(feature string, deleteBranches, forceDelete bool) (retErr error) {
	featurePath := internal.FeaturePath(feature)

	tx, err := internal.BeginSpacesFeatureDelete(internal.TwsRoot(), feature, featurePath)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, tx.Release()) }()

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature not found: %s", feature)
	}

	stack, _ := internal.LoadStack(featurePath)

	if deleteBranches || forceDelete {
		// Pre-validate: check current branch.
		currentBranch := ""
		if repoRoot, err := internal.MainRepoRoot(); err == nil {
			currentBranch = currentGitBranch(repoRoot)
		}

		var toDelete []string
		for _, entry := range stack.Branches {
			gitBranch := entry.GitBranch()
			if gitBranch == currentBranch {
				return fmt.Errorf("cannot delete branch %q: it is the currently checked-out branch; switch to another branch first", gitBranch)
			}
			toDelete = append(toDelete, gitBranch)
		}

		flag := "-d"
		if forceDelete {
			flag = "-D"
		}
		for _, branch := range toDelete {
			if err := internal.RunSilent("git", "branch", flag, branch); err != nil {
				return fmt.Errorf("failed to delete git branch %q: %w; feature metadata preserved", branch, err)
			}
		}
	}

	// Remove worktrees
	for _, entry := range stack.Branches {
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			_ = internal.Run("git", "worktree", "remove", "--force", path)
		}
	}

	if err := os.RemoveAll(featurePath); err != nil {
		return fmt.Errorf("error removing feature directory: %w", err)
	}

	fmt.Printf("Deleted feature: %s\n", feature)
	return nil
}

// currentGitBranch returns the current branch name for the given repo root.
func currentGitBranch(repoRoot string) string {
	out, err := exec.Command("git", "-C", repoRoot, "symbolic-ref", "--short", "HEAD").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func doctorCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "doctor [feature]",
		Short: "Run health checks on workspaces",
		Long: `Check workspace and stack health. With no args, checks all features.

Warnings such as a dirty checkout, active Git operation, stale ancestry, or
recoverable lock/session state are reported with exit 0 for interactive use.
Corrupt or unreadable persisted state returns a non-zero exit status.`,
		Args: cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			// Checkout mode dispatch
			ws, wsErr := internal.RequireWorkspace()
			if wsErr == nil && ws.Mode == internal.ModeCheckout {
				feature := ""
				if len(args) == 1 {
					feature = args[0]
				}
				return runCheckoutDoctor(ws, feature)
			}

			if len(args) == 1 {
				_, err := checkFeatureE(args[0])
				return err
			}

			// Check all features
			features, listErr := internal.ListFeaturesE()
			if listErr != nil {
				return listErr
			}
			if len(features) == 0 {
				fmt.Println("No features found.")
				return nil
			}

			totalIssues := 0
			for _, feature := range features {
				issues, err := checkFeatureE(feature)
				if err != nil {
					return err
				}
				totalIssues += issues
			}

			if totalIssues == 0 {
				fmt.Println("\nAll healthy.")
			} else {
				fmt.Printf("\n%d issue(s) found.\n", totalIssues)
			}
			return nil
		},
	}
}

func checkFeatureE(feature string) (int, error) {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		return 0, err
	}

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		fmt.Printf("%s: not found\n", feature)
		return 0, nil
	}

	issues := internal.CheckFeatureHealth(featurePath)

	if len(issues) == 0 {
		// Count active worktrees
		wtDir := filepath.Join(featurePath, "worktrees")
		entries, _ := os.ReadDir(wtDir)
		active := 0
		for _, e := range entries {
			if e.IsDir() {
				active++
			}
		}
		fmt.Printf("%s: healthy (%d active worktree(s))\n", feature, active)
	} else {
		fmt.Printf("%s: %d issue(s)\n", feature, len(issues))
		for _, issue := range issues {
			fmt.Println(issue)
		}
	}

	return len(issues), nil
}

func runCheckoutDoctor(ws internal.Workspace, feature string) error {
	report, err := internal.BuildCheckoutHealthReport(ws, nil)
	if err != nil {
		return err
	}
	if feature != "" {
		if err := report.FilterFeature(feature); err != nil {
			return err
		}
	}
	fmt.Print(internal.FormatCheckoutHealth(report))
	if report.HasErrors() {
		return fmt.Errorf("checkout workspace has corrupt or unreadable state")
	}
	return nil
}

package cli

import (
	"archive/tar"
	"compress/gzip"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func exportCmd() *cobra.Command {
	var output string
	var full bool
	var toRepo bool

	cmd := &cobra.Command{
		Use:   "export <feature>",
		Short: "Export workspace metadata for portability",
		Long: `Export a feature's workspace metadata (stack, decisions) to YAML or tarball.

  tws export auth                          # YAML to stdout
  tws export auth -o auth.yaml             # YAML to file
  tws export auth --full -o auth.tar.gz    # tarball with inject files
  tws export auth --to-repo                # save to .tws/workspaces/ (committed)`,
		Args: cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
				return err
			}

			var featurePath string
			featurePath, err = ws.ResolveFeaturePath(feature)
			if err != nil {
				return err
			}

			if _, err := os.Stat(featurePath); os.IsNotExist(err) {
				return fmt.Errorf("feature not found: %s", feature)
			}

			stack, _ := internal.LoadStack(featurePath)
			decisions, _ := internal.LoadDecisions(featurePath)
			export := internal.NewWorkspaceExport(feature, stack, decisions)

			if toRepo {
				if ws.Mode == internal.ModeCheckout {
					return fmt.Errorf("--to-repo is not supported in checkout mode; use '-o <tracked-path>' to write to a tracked file instead")
				}
				return exportToRepo(feature, export)
			}

			if full {
				return exportTarball(feature, featurePath, export, output)
			}

			return exportYAML(export, output)
		},
	}

	cmd.Flags().StringVarP(&output, "output", "o", "", "Output file (default: stdout)")
	cmd.Flags().BoolVar(&full, "full", false, "Include inject files in a tarball")
	cmd.Flags().BoolVar(&toRepo, "to-repo", false, "Save to .tws/workspaces/ in the repo")

	return cmd
}

func exportYAML(export internal.WorkspaceExport, output string) error {
	data, err := internal.MarshalExport(export)
	if err != nil {
		return fmt.Errorf("marshaling export: %w", err)
	}

	if output == "" {
		fmt.Print(string(data))
	} else {
		if err := os.WriteFile(output, data, 0644); err != nil {
			return fmt.Errorf("writing %s: %w", output, err)
		}
		fmt.Printf("Exported to: %s\n", output)
	}
	return nil
}

func exportToRepo(feature string, export internal.WorkspaceExport) error {
	repoRoot, err := internal.MainRepoRoot()
	if err != nil {
		return fmt.Errorf("not inside a git repository")
	}

	dir := filepath.Join(repoRoot, ".tws", "workspaces")
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	path := filepath.Join(dir, feature+".yaml")
	data, err := internal.MarshalExport(export)
	if err != nil {
		return err
	}

	if err := os.WriteFile(path, data, 0644); err != nil {
		return err
	}

	fmt.Printf("Exported to: %s\n", path)
	fmt.Println("Commit and push to share with team members.")
	return nil
}

// exportTarball creates a tarball with durable metadata and inject files.
// Runtime state (.tws/state) is structurally excluded.
func exportTarball(feature, featurePath string, export internal.WorkspaceExport, output string) error {
	if output == "" {
		output = feature + "-workspace.tar.gz"
	}

	f, err := os.Create(output)
	if err != nil {
		return fmt.Errorf("creating %s: %w", output, err)
	}
	defer f.Close() //nolint:errcheck

	gw := gzip.NewWriter(f)
	defer gw.Close() //nolint:errcheck

	tw := tar.NewWriter(gw)
	defer tw.Close() //nolint:errcheck

	// Write workspace.yaml
	yamlData, _ := internal.MarshalExport(export)
	addToTar(tw, "workspace.yaml", yamlData)

	// Write inject files only (exclude runtime state structurally)
	injectDir := internal.InjectPath(featurePath)
	if _, err := os.Stat(injectDir); err == nil {
		_ = filepath.Walk(injectDir, func(path string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() {
				return nil
			}
			relPath, _ := filepath.Rel(featurePath, path)
			// Structurally exclude runtime state: only include inject/ prefix
			if !strings.HasPrefix(relPath, "inject/") && !strings.HasPrefix(relPath, "inject\\") {
				return nil
			}
			data, err := os.ReadFile(path)
			if err != nil {
				return nil
			}
			addToTar(tw, relPath, data)
			return nil
		})
	}

	fmt.Printf("Exported to: %s\n", output)
	return nil
}

func addToTar(tw *tar.Writer, name string, data []byte) {
	header := &tar.Header{
		Name: name,
		Mode: 0644,
		Size: int64(len(data)),
	}
	_ = tw.WriteHeader(header)
	_, _ = tw.Write(data)
}

package cli

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func hooksCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "hooks",
		Short: "Manage agent hooks for auto-read decisions",
	}

	cmd.AddCommand(hooksInstallCmd())
	cmd.AddCommand(hooksRemoveCmd())

	return cmd
}

// Claude Code settings.json hook structure
type claudeSettings struct {
	Hooks map[string][]hookMatcher `json:"hooks,omitempty"`
}

type hookMatcher struct {
	Matcher string       `json:"matcher"`
	Hooks   []hookAction `json:"hooks"`
}

type hookAction struct {
	Type    string `json:"type"`
	Command string `json:"command"`
	Timeout int    `json:"timeout,omitempty"`
}

func hooksInstallCmd() *cobra.Command {
	var all bool

	cmd := &cobra.Command{
		Use:   "install [feature]",
		Short: "Install Claude Code hooks for auto-reading decisions",
		Long: `Install hooks into .claude/settings.local.json so that Claude Code
automatically checks for new decisions on session start and resume.

Use --all to install hooks across all features.
Set auto_hooks: true in config to auto-install on every tws new.`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, wsErr := internal.RequireWorkspace()
			if wsErr != nil {
				return wsErr
			}
			if ws.Mode == internal.ModeCheckout {
				return fmt.Errorf("hooks install requires linked worktrees; not supported in checkout mode")
			}

			if all {
				features, listErr := internal.ListFeaturesE()
				if listErr != nil {
					return listErr
				}
				if len(features) == 0 {
					fmt.Println("No features found.")
					return nil
				}
				for _, f := range features {
					fmt.Printf("%s:\n", f)
					installHooksForFeature(f)
				}
				return nil
			}

			var feature string
			if len(args) > 0 {
				feature = args[0]
			} else {
				feature, _ = internal.DetectFeatureFromCwd()
				if feature == "" {
					return fmt.Errorf("could not detect feature. Run from inside a worktree or specify: tws hooks install <feature>")
				}
			}

			// installHooksForFeature has no error channel and prints to
			// stdout, so the guard must be evaluated here to exit nonzero.
			if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
				return err
			}

			installHooksForFeature(feature)
			return nil
		},
	}

	cmd.Flags().BoolVar(&all, "all", false, "Install hooks for all features")

	return cmd
}

func installHooksForFeature(feature string) {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		fmt.Printf("  [x] %s: %v\n", feature, err)
		return
	}
	stack, _ := internal.LoadStack(featurePath)

	installed := 0
	for _, entry := range stack.Branches {
		wtPath, err := internal.RequireWorktreePath(feature, entry.Name)
		if err != nil {
			fmt.Printf("  [x] %s: %v\n", entry.Name, err)
			return
		}
		if _, err := os.Stat(wtPath); os.IsNotExist(err) {
			continue
		}

		if err := installHooksForWorktree(wtPath, feature); err != nil {
			fmt.Printf("  [x] %s: %v\n", entry.Name, err)
		} else {
			fmt.Printf("  [+] %s: hooks installed\n", entry.Name)
			installed++
		}
	}

	if installed > 0 {
		fmt.Printf("Installed hooks in %d worktree(s)\n", installed)
	}
}

func hooksRemoveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "remove [feature]",
		Short: "Remove auto-read decision hooks",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return fmt.Errorf("hooks remove requires linked worktrees; not supported in checkout mode")
			}

			var feature string
			if len(args) > 0 {
				feature = args[0]
			} else {
				feature, _ = internal.DetectFeatureFromCwd()
				if feature == "" {
					return fmt.Errorf("could not detect feature; specify a feature or run from inside a worktree")
				}
			}

			featurePath, fpErr := internal.RequireFeaturePath(feature)
			if fpErr != nil {
				return fpErr
			}
			stack, _ := internal.LoadStack(featurePath)

			for _, entry := range stack.Branches {
				wtPath, wtErr := internal.RequireWorktreePath(feature, entry.Name)
				if wtErr != nil {
					return wtErr
				}
				settingsPath := filepath.Join(wtPath, ".claude", "settings.local.json")
				if err := os.Remove(settingsPath); err == nil {
					fmt.Printf("  [-] %s: hooks removed\n", entry.Name)
				}
			}
			return nil
		},
	}
}

func installHooksForWorktree(wtPath, feature string) error {
	settingsDir := filepath.Join(wtPath, ".claude")
	if err := os.MkdirAll(settingsDir, 0755); err != nil {
		return err
	}

	settingsPath := filepath.Join(settingsDir, "settings.local.json")

	// Build the decisions check command
	showCmd := fmt.Sprintf("tws decisions show %s --mine 2>/dev/null || true", feature)
	ackHint := fmt.Sprintf("echo 'To acknowledge: tws decisions ack %s'", feature)
	fullCmd := showCmd + " && " + ackHint

	settings := claudeSettings{
		Hooks: map[string][]hookMatcher{
			"SessionStart": {
				{
					Matcher: "startup",
					Hooks: []hookAction{
						{Type: "command", Command: fullCmd, Timeout: 10},
					},
				},
				{
					Matcher: "resume",
					Hooks: []hookAction{
						{Type: "command", Command: showCmd, Timeout: 10},
					},
				},
			},
		},
	}

	data, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		return err
	}

	return os.WriteFile(settingsPath, data, 0644)
}

package cli

import (
	"archive/tar"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func importCmd() *cobra.Command {
	var fromRepo string

	cmd := &cobra.Command{
		Use:   "import [file]",
		Short: "Import workspace from YAML or tarball",
		Long: `Recreate a workspace from an exported YAML or tarball.

  tws import auth-workspace.yaml           # from YAML file
  tws import auth-workspace.tar.gz         # from tarball (includes inject files)
  tws import --from-repo auth              # from .tws/workspaces/auth.yaml`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if fromRepo != "" {
				return importFromRepoE(fromRepo, ws)
			}

			if len(args) == 0 {
				return fmt.Errorf("usage: tws import <file> or tws import --from-repo <feature>")
			}

			file := args[0]
			if strings.HasSuffix(file, ".tar.gz") || strings.HasSuffix(file, ".tgz") {
				return importTarballE(file, ws)
			}
			return importYAMLE(file, ws)
		},
	}

	cmd.Flags().StringVar(&fromRepo, "from-repo", "", "Import from .tws/workspaces/<feature>.yaml")

	return cmd
}

func importFromRepoE(feature string, ws internal.Workspace) error {
	repoRoot, err := internal.MainRepoRoot()
	if err != nil {
		return fmt.Errorf("not inside a git repository")
	}

	path := filepath.Join(repoRoot, ".tws", "workspaces", feature+".yaml")
	return importYAMLE(path, ws)
}

func importYAMLE(file string, ws internal.Workspace) error {
	data, err := os.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading %s: %w", file, err)
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing %s: %w", file, err)
	}

	return recreateWorkspaceE(export, "", ws)
}

func importTarballE(file string, ws internal.Workspace) error {
	f, err := os.Open(file)
	if err != nil {
		return fmt.Errorf("opening %s: %w", file, err)
	}
	defer f.Close() //nolint:errcheck

	gr, err := gzip.NewReader(f)
	if err != nil {
		return fmt.Errorf("not a valid gzip file: %w", err)
	}
	defer gr.Close() //nolint:errcheck

	tmpDir, err := os.MkdirTemp("", "tws-import-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir) //nolint:errcheck

	tr := tar.NewReader(gr)
	for {
		header, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("reading tarball: %w", err)
		}

		if isRuntimeState(header.Name) {
			continue
		}
		target, err := safeArchiveTarget(tmpDir, header.Name)
		if err != nil {
			return err
		}
		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, 0755); err != nil {
				return fmt.Errorf("creating archive directory %s: %w", header.Name, err)
			}
		case tar.TypeReg:
			if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
				return fmt.Errorf("creating parent for %s: %w", header.Name, err)
			}
			outFile, err := os.OpenFile(target, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
			if err != nil {
				return fmt.Errorf("creating extracted file %s: %w", header.Name, err)
			}
			if _, copyErr := io.Copy(outFile, tr); copyErr != nil {
				_ = outFile.Close()
				return fmt.Errorf("extracting %s: %w", header.Name, copyErr)
			}
			if err := outFile.Close(); err != nil {
				return fmt.Errorf("closing extracted file %s: %w", header.Name, err)
			}
		default:
			return fmt.Errorf("unsupported archive entry %q (type %d)", header.Name, header.Typeflag)
		}
	}

	data, err := os.ReadFile(filepath.Join(tmpDir, "workspace.yaml"))
	if err != nil {
		return fmt.Errorf("tarball missing workspace.yaml")
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing workspace.yaml: %w", err)
	}

	injectSrc := filepath.Join(tmpDir, "inject")
	return recreateWorkspaceE(export, injectSrc, ws)
}

func safeArchiveTarget(root, name string) (string, error) {
	if name == "" || filepath.IsAbs(name) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	clean := filepath.Clean(filepath.FromSlash(name))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	root = filepath.Clean(root)
	target := filepath.Join(root, clean)
	rel, err := filepath.Rel(root, target)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("archive path escapes destination: %q", name)
	}
	return target, nil
}

// isRuntimeState returns true for explicit runtime-state paths.
func isRuntimeState(path string) bool {
	normalized := filepath.ToSlash(path)
	return strings.HasPrefix(normalized, ".tws/state/") ||
		normalized == ".tws/state" ||
		normalized == ".sync-state.yaml"
}

func recreateWorkspaceE(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	if ws.Mode == internal.ModeCheckout {
		return recreateCheckout(export, injectSrc, ws)
	}
	return recreateExternal(export, injectSrc)
}

// recreateCheckout imports into checkout mode: restores under .tws/features/,
// creates/registers branches without linked worktrees, never imports runtime state.
func recreateCheckout(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	feature := export.Feature
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath := ws.FeaturePath(feature)

	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return fmt.Errorf("creating feature directory: %w", err)
	}

	// FEATURE.md
	featureMD := filepath.Join(featurePath, "FEATURE.md")
	if _, err := os.Stat(featureMD); os.IsNotExist(err) {
		_ = os.WriteFile(featureMD, []byte("# "+feature+"\n"), 0644)
	}

	// Stack
	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			return fmt.Errorf("writing stack.yaml: %w", err)
		}
		fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
	}

	// Decisions
	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	// Inject files
	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	// Register branches (no worktrees in checkout mode)
	for _, entry := range export.Stack.Branches {
		gitBranch := entry.GitBranch()
		if internal.VerifyGitRef(ws.RepoRoot, gitBranch) == nil {
			fmt.Printf("  [=] %s (branch exists: %s)\n", entry.Name, gitBranch)
		} else {
			fmt.Printf("  [-] %s (branch %s not found — fetch from remote first)\n", entry.Name, gitBranch)
		}
	}

	fmt.Printf("Imported feature: %s (checkout mode — no worktrees created)\n", feature)
	return nil
}

// recreateExternal imports into external mode (original behavior).
func recreateExternal(export internal.WorkspaceExport, injectSrc string) error {
	feature := export.Feature
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	os.MkdirAll(filepath.Join(featurePath, "worktrees"), 0755) //nolint:errcheck

	if _, err := os.Stat(filepath.Join(featurePath, "FEATURE.md")); os.IsNotExist(err) {
		os.WriteFile(filepath.Join(featurePath, "FEATURE.md"), []byte("# "+feature+"\n"), 0644) //nolint:errcheck
	}

	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			fmt.Printf("Warning: could not write stack.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
		}
	}

	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	injectDir := internal.InjectPath(featurePath)
	os.MkdirAll(injectDir, 0755) //nolint:errcheck
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	for _, entry := range export.Stack.Branches {
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			fmt.Printf("  [=] %s (already exists)\n", entry.Name)
			continue
		}

		if internal.BranchExists(entry.Name) {
			err := internal.RunSilent("git", "worktree", "add", "--force", path, entry.Name)
			if err != nil {
				fmt.Printf("  [x] %s (checkout failed)\n", entry.Name)
			} else {
				fmt.Printf("  [+] %s (checked out)\n", entry.Name)
			}
		} else {
			fmt.Printf("  [-] %s (branch not found — fetch from remote first)\n", entry.Name)
		}
	}

	target := internal.ResolveInjectInto("")
	count, _ := internal.InjectFilesForFeature(featurePath, target)
	if count > 0 {
		fmt.Printf("  Injected files into %d worktree(s)\n", count)
	}

	fmt.Printf("Imported feature: %s\n", feature)
	return nil
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func listCmd() *cobra.Command {
	return &cobra.Command{
		Use:     "list",
		Aliases: []string{"ls"},
		Short:   "List features and branches",
		Args:    cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				// Fallback to legacy TwsRoot for external mode compat.
				wsRoot := internal.TwsRoot()
				if _, serr := os.Stat(wsRoot); os.IsNotExist(serr) {
					fmt.Println("No workspace found. Use 'tws init --mode checkout' or 'tws enable --mode checkout'.")
					return nil
				}
				// Build a minimal workspace for listing.
				ws = internal.Workspace{MetadataRoot: wsRoot, Mode: internal.ModeExternal}
			}

			// Checkout mode dispatch
			if ws.Mode == internal.ModeCheckout {
				return runCheckoutList(ws)
			}

			features, listErr := ws.ListFeaturesResolved()
			if listErr != nil {
				return listErr
			}

			if len(features) == 0 {
				fmt.Println("No features found. Use 'tws add <feature>' to create one.")
				return nil
			}

			fmt.Printf("Workspace: %s (mode: %s)\n\n", ws.MetadataRoot, ws.Mode)

			// Deliberately guard-free: ListFeaturesResolved has already removed
			// space-owned names, and an untrusted spaces.yaml aborted above.
			for _, feature := range features {
				featurePath, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					// Ambiguity error — report it inline.
					fmt.Printf("%s\n  ERROR: %v\n\n", feature, resolveErr)
					continue
				}

				fmt.Printf("%s\n", feature)

				stack, serr := internal.LoadStack(featurePath)
				if serr == nil && len(stack.Branches) > 0 {
					for i, entry := range stack.Branches {
						wtPath := filepath.Join(featurePath, "worktrees", entry.Name)
						status := "active"
						if _, err := os.Stat(wtPath); os.IsNotExist(err) {
							if internal.IsPrunableWorktree(entry.Name) {
								status = "missing"
							} else {
								status = "archived"
							}
						}

						tmuxTag := ""
						session := sanitizeSessionName(feature + "/" + entry.Name)
						if sessionExists(session) {
							tmuxTag = " [tmux]"
						}

						healthTag := ""
						if status == "active" {
							if issue := internal.CheckWorktreeBranch(wtPath, entry.Name); issue != nil {
								healthTag = " [wrong-branch!]"
							}
						}

						connector := "├──"
						if i == len(stack.Branches)-1 {
							connector = "└──"
						}
						fmt.Printf("  %s %s (base: %s) [%s]%s%s\n", connector, entry.Name, entry.Base, status, tmuxTag, healthTag)
					}
				} else {
					wtDir := filepath.Join(featurePath, "worktrees")
					wts, rErr := os.ReadDir(wtDir)
					if rErr != nil || len(wts) == 0 {
						fmt.Println("  (no branches)")
					} else {
						for i, wt := range wts {
							if !wt.IsDir() {
								continue
							}
							connector := "├──"
							if i == len(wts)-1 {
								connector = "└──"
							}
							fmt.Printf("  %s %s\n", connector, wt.Name())
						}
					}
				}
				fmt.Println()
			}
			return nil
		},
	}
}

func runCheckoutList(ws internal.Workspace) error {
	entries, err := internal.BuildCheckoutList(ws)
	if err != nil {
		return err
	}
	fmt.Print(internal.FormatCheckoutList(ws, entries))
	return nil
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func newCmd() *cobra.Command {
	var base string
	var force bool
	var repo string

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				if repo != "" {
					return fmt.Errorf("--repo is not supported in checkout mode; checkout workspaces use exactly one repository")
				}
				return createCheckoutBranch(ws, args[0], args[1], base, force)
			}
			return createWorktree(args[0], args[1], base, repo, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "", "Parent branch, tag, or commit (default: selected repo's origin/HEAD)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().StringVar(&repo, "repo", "", "Source repository path (for cross-repo worktrees)")

	return cmd
}

// createCheckoutBranch creates a git branch for checkout mode (no worktree).
// Atomic: if metadata persistence fails after branch creation, the branch is
// rolled back (only if this operation created it). Archived entries are
// reactivated. Mismatched existing entries are rejected.
func createCheckoutBranch(ws internal.Workspace, feature, name, requestedBase string, force bool) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	// Pre-validate feature directory exists.
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature %q not found; run 'tws add %s' first", feature, feature)
	}

	stack, _ := internal.LoadStack(featurePath)

	repoRoot := ws.RepoRoot

	baseName, baseRef, err := resolveCreationBase(repoRoot, "", stack, requestedBase)
	if err != nil {
		return err
	}

	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExisted := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if !branchExisted && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExisted = true
	}

	// Check for existing stack entry.
	existing := internal.GetBranch(stack, name)
	if existing.Name != "" {
		// If archived, reactivate.
		if existing.Archived {
			for i := range stack.Branches {
				if stack.Branches[i].Name == name {
					stack.Branches[i].Archived = false
					break
				}
			}
			if err := internal.SaveStack(featurePath, stack); err != nil {
				return fmt.Errorf("failed to unarchive branch: %w", err)
			}
			fmt.Printf("Reactivated archived branch: %s (git: %s)\n", name, existing.GitBranch())
			return nil
		}
		// Existing non-archived entry: validate consistency.
		expectedBranch := gitBranch
		if existing.Branch != "" {
			expectedBranch = existing.Branch
		}
		if existing.GitBranch() != expectedBranch && existing.GitBranch() != gitBranch {
			return fmt.Errorf("branch %q already registered with git branch %q (expected %q); use rename or delete first",
				name, existing.GitBranch(), gitBranch)
		}
		fmt.Printf("Branch %s already registered (git: %s)\n", name, existing.GitBranch())
		return nil
	}

	// Create git branch if it does not exist.
	if !branchExisted {
		if err := internal.RunDir(repoRoot, "git", "branch", gitBranch, baseRef); err != nil {
			return fmt.Errorf("creating git branch %s: %w", gitBranch, err)
		}
	}

	// Register in stack.
	entry := internal.StackEntry{
		Name: name,
		Base: baseName,
	}
	if gitBranch != name {
		entry.Branch = gitBranch
	}
	stack.Branches = append(stack.Branches, entry)

	if err := internal.SaveStack(featurePath, stack); err != nil {
		// Rollback: only delete branch if we created it.
		if !branchExisted {
			_ = internal.RunSilentDir(repoRoot, "git", "branch", "-d", gitBranch)
		}
		return fmt.Errorf("failed to persist stack (branch rolled back): %w", err)
	}

	fmt.Printf("Branch created: %s (git: %s, base: %s)\n", name, gitBranch, baseName)
	return nil
}

// openCheckoutTmux opens a tmux session for a checkout-mode branch.
func openCheckoutTmux(ws internal.Workspace, feature, branch string) {
	session := sanitizeSessionName(feature + "/" + branch)
	fmt.Printf("Checkout branch: use 'git checkout %s' then 'tmux new-session -s %s'\n", branch, session)
}

// createWorktree is the shared logic for creating a worktree branch (external mode).
// Used by both tws new and tws add -n. Explicit base refs are literal;
// an omitted base resolves from the selected repository's origin/HEAD.
func createWorktree(feature, name, requestedBase, repoPath string, force bool) error {
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, name)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return err
	}

	stack, _ := internal.LoadStack(featurePath)
	repoRoot, storedRepo, err := resolveSourceRepo(featurePath, stack, repoPath)
	if err != nil {
		return err
	}

	baseName, baseRef, err := resolveCreationBase(repoRoot, storedRepo, stack, requestedBase)
	if err != nil {
		return err
	}

	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExists := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if !branchExists && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExists = true
	}

	if branchExists {
		if isCheckedOutIn(repoRoot, gitBranch) && !force {
			return fmt.Errorf("branch %q is already checked out in another worktree; use --force to check it out anyway", gitBranch)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, gitBranch)
		if err := internal.RunDir(repoRoot, "git", gitArgs...); err != nil {
			return err
		}
	} else {
		if err := internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", gitBranch, baseRef); err != nil {
			return err
		}
	}

	if !internal.HasBranch(stack, name) {
		entry := internal.StackEntry{
			Name: name,
			Base: baseName,
			Repo: storedRepo,
		}
		if gitBranch != name {
			entry.Branch = gitBranch
		}
		stack.Branches = append(stack.Branches, entry)
		if err := internal.SaveStack(featurePath, stack); err != nil {
			return err
		}
	}

	target := internal.ResolveInjectInto("")
	if err := internal.InjectFiles(featurePath, path, target); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	if cfg.AutoHooks != nil && *cfg.AutoHooks {
		if err := installHooksForWorktree(path, feature); err != nil {
			fmt.Printf("Warning: auto-hooks install failed: %v\n", err)
		}
	}

	if storedRepo != "" {
		fmt.Printf("Worktree created: %s (base: %s, repo: %s)\n", path, baseName, storedRepo)
	} else {
		fmt.Printf("Worktree created: %s (base: %s)\n", path, baseName)
	}
	return nil
}

func resolveSourceRepo(featurePath string, stack internal.Stack, requestedRepo string) (string, string, error) {
	if requestedRepo != "" {
		absRepo, err := internal.AbsPath(requestedRepo)
		if err != nil {
			return "", "", fmt.Errorf("invalid repo path %s: %w", requestedRepo, err)
		}
		repoRoot, err := internal.GitRepoRootIn(absRepo)
		if err != nil {
			return "", "", fmt.Errorf("%s is not a Git repository", requestedRepo)
		}
		return repoRoot, repoRoot, nil
	}

	if repoRoot, err := internal.MainRepoRoot(); err == nil {
		return repoRoot, "", nil
	}

	type candidate struct {
		root       string
		storedRepo string
	}
	candidates := make(map[string]candidate)
	for _, entry := range stack.Branches {
		if entry.Repo != "" {
			root, err := internal.GitRepoRootIn(entry.Repo)
			if err == nil {
				candidates[root] = candidate{root: root, storedRepo: root}
			}
			continue
		}

		worktreePath := filepath.Join(featurePath, "worktrees", entry.Name)
		if _, err := os.Stat(worktreePath); err != nil {
			continue
		}
		root, err := internal.MainRepoRootIn(worktreePath)
		if err == nil {
			candidates[root] = candidate{root: root}
		}
	}

	if len(candidates) == 1 {
		for _, c := range candidates {
			return c.root, c.storedRepo, nil
		}
	}
	if len(candidates) > 1 {
		return "", "", fmt.Errorf("feature uses multiple repositories; specify --repo")
	}
	return "", "", fmt.Errorf("could not infer source repository; run from a Git repo or specify --repo")
}

func resolveCreationBase(repoRoot, storedRepo string, stack internal.Stack, requestedBase string) (string, string, error) {
	if requestedBase == "" {
		baseName, err := internal.DefaultBranchIn(repoRoot)
		if err != nil {
			return "", "", err
		}
		remoteRef := "origin/" + baseName
		if internal.VerifyGitRef(repoRoot, remoteRef) == nil {
			return baseName, remoteRef, nil
		}
		if internal.VerifyGitRef(repoRoot, baseName) == nil {
			return baseName, baseName, nil
		}
		return "", "", fmt.Errorf("default branch %q does not exist in %s", baseName, repoRoot)
	}

	baseRef := requestedBase
	if parent := internal.GetBranch(stack, requestedBase); parent.Name != "" {
		if !sameStackRepo(parent.Repo, storedRepo) {
			return "", "", fmt.Errorf("base %q belongs to a different repository", requestedBase)
		}
		baseRef = parent.GitBranch()
	}
	if err := internal.VerifyGitRef(repoRoot, baseRef); err != nil {
		return "", "", fmt.Errorf("base ref %q does not exist in %s", requestedBase, repoRoot)
	}
	return requestedBase, baseRef, nil
}

func sameStackRepo(a, b string) bool {
	if a == "" && b == "" {
		return true
	}
	return a == b
}

func isCheckedOutIn(repoRoot, branch string) bool {
	out, err := exec.Command("git", "-C", repoRoot, "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for line := range strings.SplitSeq(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool
	var featureDir bool
	var all bool

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open worktree and run agent",
		Long: `Open a worktree and run the configured agent. With no args, shows an interactive picker.

Use --feature-dir to open the feature directory itself (orchestrator mode).
Use --all to create a tmux session with windows for every worktree in the feature.`,
		Args: cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// Checkout mode: delegate to checkout session flow
			if ws.Mode == internal.ModeCheckout {
				if all {
					return fmt.Errorf("--all not supported in checkout mode")
				}

				// --feature-dir handled before branch resolution
				if featureDir {
					if len(args) < 1 {
						return fmt.Errorf("usage: tws open <feature> --feature-dir")
					}
					feature := args[0]
					if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
						return gerr
					}
					fp, ferr := ws.ResolveFeaturePath(feature)
					if ferr != nil {
						return ferr
					}
					if noAgent {
						fmt.Printf("cd %s\n", fp)
						return nil
					}
					fmt.Printf("Opening feature dir: %s\n", fp)
					openDirect(fp)
					return nil
				}

				return runCheckoutOpen(ws, args, useTmux, noTmux, noAgent, cmd.Flags())
			}

			// Handle --all: tmux session with all worktrees
			if all {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --all")
				}
				// Guard before openAll, which has no error channel.
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), args[0]); gerr != nil {
					return gerr
				}
				openAll(args[0])
				return nil
			}

			// Handle --feature-dir: open the feature directory
			if featureDir {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --feature-dir")
				}
				feature := args[0]
				// Guard before openDirect, which has no error channel.
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), feature); gerr != nil {
					return gerr
				}
				path := internal.FeaturePath(feature)
				if _, err := os.Stat(path); os.IsNotExist(err) {
					return fmt.Errorf("feature not found: %s", feature)
				}
				if noAgent {
					fmt.Printf("cd %s\n", path)
					return nil
				}
				fmt.Printf("Opening feature dir: %s\n", path)
				openDirect(path)
				return nil
			}

			// Normal mode: open a specific worktree
			if len(args) >= 1 {
				// The 0-arg picker is covered by ListFeaturesE inside
				// resolveOpenArgs.
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), args[0]); gerr != nil {
					return gerr
				}
			}
			feature, branch, err := resolveOpenArgs(args)
			if err != nil {
				return err
			}

			path := internal.WorktreePath(feature, branch)

			if _, err := os.Stat(path); os.IsNotExist(err) {
				return fmt.Errorf("worktree not found: %s", path)
			}

			// Re-sync inject files
			featurePath := internal.FeaturePath(feature)
			injectTarget := internal.ResolveInjectInto("")
			if err := internal.InjectFiles(featurePath, path, injectTarget); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return nil
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				openWithTmux(feature, branch, path)
			} else {
				// Warn if there's a stale tmux session
				session := sanitizeSessionName(feature + "/" + branch)
				if sessionExists(session) {
					fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
					fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
				}
				openDirect(path)
			}
			return nil
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Just print the worktree path")
	cmd.Flags().BoolVar(&featureDir, "feature-dir", false, "Open the feature directory (orchestrator mode)")
	cmd.Flags().BoolVar(&all, "all", false, "Create tmux session with windows for all worktrees")

	return cmd
}

func resolveOpenArgs(args []string) (string, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		return args[0], args[1], nil
	case 1:
		feature = args[0]
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	case 0:
		features, listErr := internal.ListFeaturesE()
		if listErr != nil {
			return "", "", listErr
		}
		if len(features) == 0 {
			return "", "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return "", "", err
		}
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	}
	return "", "", fmt.Errorf("unexpected args")
}

func openDirect(path string) {
	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	parts := strings.Fields(agentCmd)
	if _, err := exec.LookPath(parts[0]); err != nil {
		fmt.Printf("Error: agent %q not found in PATH\n", parts[0])
		os.Exit(1)
	}

	fmt.Printf("Opening: %s\nRunning: %s\n", path, agentCmd)

	// Run agent as subprocess in the worktree directory
	agent := exec.Command(parts[0], parts[1:]...)
	agent.Dir = path
	agent.Stdin = os.Stdin
	agent.Stdout = os.Stdout
	agent.Stderr = os.Stderr

	if err := agent.Run(); err != nil {
		fmt.Printf("Agent exited: %v\n", err)
	}

	// Spawn an interactive shell in the worktree dir so the user stays there
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}

	fmt.Printf("Dropped into shell at: %s\n", path)
	sh := exec.Command(shell)
	sh.Dir = path
	sh.Stdin = os.Stdin
	sh.Stdout = os.Stdout
	sh.Stderr = os.Stderr
	_ = sh.Run()
}

// openAll creates a tmux session with the feature dir as the first window
// and one window per active worktree.
func openAll(feature string) {
	internal.RequireTool("tmux")

	featurePath := internal.FeaturePath(feature)
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		fmt.Printf("Feature not found: %s\n", feature)
		os.Exit(1)
	}

	session := sanitizeSessionName(feature)

	// Kill existing session if any
	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	// Create session with feature dir as first window
	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", featurePath, "-n", "orchestrator"))

	// Add a window for each active worktree
	branches := internal.ListBranches(feature)
	for _, branch := range branches {
		wtPath := internal.WorktreePath(feature, branch)
		if _, err := os.Stat(wtPath); os.IsNotExist(err) {
			continue // archived
		}
		windowName := sanitizeSessionName(branch)
		_ = internal.RunSilent("tmux", "new-window", "-t", session, "-n", windowName, "-c", wtPath)
	}

	// Select the orchestrator window
	_ = internal.RunSilent("tmux", "select-window", "-t", session+":orchestrator")

	// Attach
	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func openWithTmux(feature, branch, path string) {
	internal.RequireTool("tmux")

	session := sanitizeSessionName(feature + "/" + branch)

	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path))

	fmt.Printf("Running: %s\n", agentCmd)
	internal.Must(internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"))

	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	r := strings.NewReplacer(".", "_", ":", "_", "/", "-")
	return r.Replace(s)
}

func isClaudeAgent(cmd string) bool {
	base := strings.Fields(cmd)[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package cli

import (
	"fmt"
	"sort"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func runCheckoutOpen(ws internal.Workspace, args []string, useTmux, noTmux, noAgent bool, cmdFlag interface{ Changed(string) bool }) error {
	// Guarded at the top: resolveCheckoutOpenArgs already resolves feature
	// paths and loads stacks for a named feature.
	if len(args) >= 1 {
		if err := internal.GuardFeatureName(ws.MetadataRoot, args[0]); err != nil {
			return err
		}
	}
	feature, name, err := resolveCheckoutOpenArgs(ws, args)
	if err != nil {
		return err
	}
	if noAgent {
		fmt.Println(ws.RepoRoot)
		return nil
	}
	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}
	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return err
	}
	entry := internal.GetBranch(stack, name)
	if entry.Name == "" {
		return fmt.Errorf("branch %q not found in feature %q", name, feature)
	}
	cfg := internal.LoadConfig()
	command := internal.CheckoutSessionAgentCommand(cfg.GetAgentCommand(), ws.RepoRoot)
	tmux := useTmux
	if !cmdFlag.Changed("tmux") && !noTmux && cfg.UseTmux != nil {
		tmux = *cfg.UseTmux
	}
	if noTmux {
		tmux = false
	}
	if tmux {
		return internal.OpenCheckoutTmux(ws, feature, entry, command, nil, internal.ResolveInjectInto(""))
	}
	return internal.OpenCheckoutDirect(ws, feature, entry, command, nil, nil, internal.ResolveInjectInto(""))
}

func resolveCheckoutOpenArgs(ws internal.Workspace, args []string) (string, string, error) {
	switch len(args) {
	case 2:
		return args[0], args[1], nil
	case 1:
		names, err := checkoutActiveNames(ws, args[0])
		if err != nil {
			return "", "", err
		}
		if len(names) == 1 {
			return args[0], names[0], nil
		}
		name, err := pick("Select branch:", names)
		return args[0], name, err
	case 0:
		features, err := ws.ListFeaturesResolved()
		if err != nil {
			return "", "", err
		}
		if len(features) == 0 {
			return "", "", fmt.Errorf("no features found")
		}
		feature := features[0]
		if len(features) > 1 {
			feature, err = pick("Select feature:", features)
			if err != nil {
				return "", "", err
			}
		}
		names, err := checkoutActiveNames(ws, feature)
		if err != nil {
			return "", "", err
		}
		if len(names) == 1 {
			return feature, names[0], nil
		}
		name, err := pick("Select branch:", names)
		return feature, name, err
	default:
		return "", "", fmt.Errorf("too many arguments")
	}
}
func checkoutActiveNames(ws internal.Workspace, feature string) ([]string, error) {
	path, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return nil, err
	}
	stack, err := internal.LoadStack(path)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, entry := range stack.Branches {
		if !entry.Archived && entry.Repo == "" {
			names = append(names, entry.Name)
		}
	}
	sort.Strings(names)
	if len(names) == 0 {
		return nil, fmt.Errorf("no active branches in feature %q", feature)
	}
	return names, nil
}

package cli

import (
	"errors"
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func renameCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "rename",
		Short: "Rename a feature or branch",
	}

	cmd.AddCommand(renameFeatureCmd())
	cmd.AddCommand(renameBranchCmd())

	return cmd
}

func renameFeatureCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "feature <old-name> <new-name>",
		Short: "Rename a feature",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			oldName := args[0]
			newName := args[1]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			root := ws.MetadataRoot

			var oldPath, newPath string
			oldPath, err = ws.ResolveFeaturePath(oldName)
			if err != nil {
				return err
			}
			newPath = ws.FeaturePath(newName)

			if _, err := os.Stat(oldPath); os.IsNotExist(err) {
				return fmt.Errorf("feature not found: %s", oldName)
			}

			// One locked read validates both names and stages the registry
			// rewrite. It runs before the destination-collision check so a
			// registered space directory reports the space conflict rather
			// than "feature already exists". With no spaces.yaml this is a
			// true no-op: no lock file, no registry file, nothing created.
			tx, err := internal.BeginSpacesFeatureRename(root, oldName, newName, oldPath, newPath)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, tx.Release()) }()

			if _, err := os.Stat(newPath); err == nil {
				return fmt.Errorf("feature already exists: %s", newName)
			}

			if err := os.Rename(oldPath, newPath); err != nil {
				return fmt.Errorf("error renaming: %w", err)
			}

			if commitErr := tx.Commit(); commitErr != nil {
				if rollbackErr := os.Rename(newPath, oldPath); rollbackErr != nil {
					return errors.Join(commitErr, fmt.Errorf(
						"rollback failed: feature directory is now %s on disk while %s still refers to %q; repair with 'tws space remove' and 'tws space add': %w",
						newPath, internal.SpacesFilePath(root), oldName, rollbackErr))
				}
				return commitErr
			}

			fmt.Printf("Renamed feature: %s → %s\n", oldName, newName)
			return nil
		},
	}
}

func renameBranchCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "branch <feature> <old-name> <new-name>",
		Short: "Rename a branch within a feature",
		Args:  cobra.ExactArgs(3),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			feature := args[0]
			oldName := args[1]
			newName := args[2]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return renameBranchCheckout(ws, feature, oldName, newName)
			}
			return renameBranchExternal(feature, oldName, newName)
		},
	}
}

// renameBranchCheckout renames a branch in checkout mode.
// Uses entry.GitBranch() for git operations (honoring prefixes).
// Short Name is the metadata identity; git branch may have a prefix.
// Metadata is updated only after git succeeds; rolled back if SaveStack fails.
func renameBranchCheckout(ws internal.Workspace, feature, oldName, newName string) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	entry := internal.GetBranch(stack, oldName)
	if entry.Name == "" {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	oldGitBranch := entry.GitBranch()

	// Compute new git branch name: preserve prefix structure.
	cfg := internal.LoadConfig()
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	// Git rename using GitBranch() (the actual branch name, possibly prefixed).
	if err := internal.RunDir(ws.RepoRoot, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
		return fmt.Errorf("error renaming git branch %s -> %s: %w", oldGitBranch, newGitBranch, err)
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	// Update Branch field if the new git branch differs from the new name.
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		if rollbackErr := internal.RunSilentDir(ws.RepoRoot, "git", "branch", "-m", newGitBranch, oldGitBranch); rollbackErr != nil {
			return fmt.Errorf("error saving stack: %w; rollback of git branch also failed: %v", err, rollbackErr)
		}
		return fmt.Errorf("error saving stack (git branch rolled back): %w", err)
	}

	// Update decisions.yaml branch references.
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

// renameBranchExternal renames a branch in external mode.
// Uses entry.GitBranch() for git operations.
func renameBranchExternal(feature, oldName, newName string) error {
	if err := internal.GuardFeatureName(internal.TwsRoot(), feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	if !internal.HasBranch(stack, oldName) {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	entry := internal.GetBranch(stack, oldName)
	oldGitBranch := entry.GitBranch()

	// Compute new git branch name preserving prefix.
	cfg := internal.LoadConfig()
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	gitDir := resolveGitDir(featurePath, stack)
	if gitDir == "" {
		return fmt.Errorf("could not find a git context; run from inside the repo or ensure at least one active worktree exists")
	}

	oldPath := internal.WorktreePath(feature, oldName)
	newPath := internal.WorktreePath(feature, newName)

	if _, err := os.Stat(oldPath); err == nil {
		// Active worktree: remove, rename branch, re-add
		if err := internal.RunDir(gitDir, "git", "worktree", "remove", "--force", oldPath); err != nil {
			return fmt.Errorf("error removing worktree: %w", err)
		}
		if err := internal.RunDir(gitDir, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
			_ = internal.RunDir(gitDir, "git", "worktree", "add", oldPath, oldGitBranch)
			return fmt.Errorf("error renaming git branch: %w", err)
		}
		if err := internal.RunDir(gitDir, "git", "worktree", "add", newPath, newGitBranch); err != nil {
			return fmt.Errorf("error creating new worktree: %w", err)
		}

		target := internal.ResolveInjectInto("")
		if injectErr := internal.InjectFiles(featurePath, newPath, target); injectErr != nil {
			fmt.Printf("Warning: inject failed: %v\n", injectErr)
		}
	} else {
		// Archived: just rename the git branch
		if err := internal.RunDir(gitDir, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
			return fmt.Errorf("error renaming git branch: %w", err)
		}
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		return fmt.Errorf("error saving stack: %w", err)
	}

	// Kill stale tmux session
	oldSession := sanitizeSessionName(feature + "/" + oldName)
	if sessionExists(oldSession) {
		_ = internal.RunSilent("tmux", "kill-session", "-t", oldSession)
	}

	// Update decisions.yaml branch references
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

// resolveGitDir finds a usable git directory from the feature's worktrees.
// Returns the path to an active worktree, or tries cwd as fallback.
func resolveGitDir(featurePath string, stack internal.Stack) string {
	// Try active worktrees first
	for _, entry := range stack.Branches {
		// Reconstruct from featurePath directly
		path := featurePath + "/worktrees/" + entry.Name
		if _, err := os.Stat(path); err == nil {
			return path
		}
		if entry.Repo != "" {
			return entry.Repo
		}
	}

	// Fallback: try cwd
	if internal.BranchExists("HEAD") {
		cwd, _ := os.Getwd()
		return cwd
	}

	return ""
}

package cli

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func spaceCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "space",
		Short: "Manage workspace sibling space links",
		Long: `Record where tool-owned sibling spaces live (learning notes, ticket stores,
patch metadata, research, documentation) in <workspace-root>/spaces.yaml.

tws is authoritative for the location only. It never reads, writes, validates,
or deletes the content of a linked space, and 'tws space remove' never deletes
the target directory.`,
	}

	cmd.AddCommand(
		spaceAddCmd(),
		spaceListCmd(),
		spaceShowCmd(),
		spaceRemoveCmd(),
	)

	return cmd
}

// completeSpaceNames offers registered space names. Completion has no error
// channel, so failures yield no candidates.
func completeSpaceNames(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	if len(args) > 0 {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	anchor, err := internal.ResolveSpacesAnchor()
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	views, err := internal.SpaceList(anchor, internal.SpaceListOptions{All: true})
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	seen := make(map[string]bool, len(views.Views))
	var names []string
	for _, v := range views.Views {
		if seen[v.Name] {
			continue
		}
		seen[v.Name] = true
		names = append(names, v.Name)
	}
	return names, cobra.ShellCompDirectiveNoFileComp
}

func registerSpaceScopeCompletions(cmd *cobra.Command) {
	_ = cmd.RegisterFlagCompletionFunc("feature",
		func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
		})
}

func spaceAddCmd() *cobra.Command {
	var kind string
	var description string
	var feature string

	cmd := &cobra.Command{
		Use:   "add <name> <path>",
		Short: "Register a sibling space",
		Long: `Register a sibling directory under a stable name.

The target must already exist and be a directory; it does not need to be a Git
repository. Targets inside the workspace root are stored workspace-relative;
targets outside are stored absolute. tws never creates the target.`,
		Args: cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			anchor, err := internal.ResolveSpacesAnchor()
			if err != nil {
				return err
			}

			entry, created, err := internal.SpaceAdd(anchor, internal.SpaceAddRequest{
				Name:        args[0],
				Path:        args[1],
				Kind:        kind,
				Description: description,
				Feature:     feature,
			})
			if err != nil {
				return err
			}

			if !created {
				_, _ = fmt.Fprintf(cmd.OutOrStdout(), "already registered: %s\n", entry.Name)
				return nil
			}

			resolved := internal.SpaceResolvedPath(anchor, entry.Path)
			scope := ""
			if entry.Feature != "" {
				scope = fmt.Sprintf(" [feature: %s]", entry.Feature)
			}
			_, _ = fmt.Fprintf(cmd.OutOrStdout(), "registered: %s (%s)%s -> %s\n",
				entry.Name, entry.Kind, scope, resolved)
			return nil
		},
	}

	cmd.Flags().StringVar(&kind, "kind", "", "Space kind (e.g. learning, tickets, patching, research, docs)")
	cmd.Flags().StringVar(&description, "description", "", "Short description (max 200 chars, single line)")
	cmd.Flags().StringVar(&feature, "feature", "", "Scope the space to a feature")
	_ = cmd.MarkFlagRequired("kind")
	_ = cmd.RegisterFlagCompletionFunc("kind",
		func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			return internal.SpaceConventionalKinds, cobra.ShellCompDirectiveNoFileComp
		})
	registerSpaceScopeCompletions(cmd)

	return cmd
}

func spaceListCmd() *cobra.Command {
	var feature string
	var all bool
	var kind string
	var jsonOutput bool

	cmd := &cobra.Command{
		Use:   "list",
		Short: "List registered sibling spaces",
		Long: `List the sibling spaces registered in this workspace.

Scope. With no flags the listing follows your current location: it always shows
every workspace-wide entry, plus the entries of the feature you are inside when
one is auto-detected. Outside any feature the bare listing is already complete.
Pass --all for the complete registry regardless of location, --feature <name>
to scope to a specific feature instead of the detected one, and --kind <kind>
to filter by kind.

Output. The human listing always prints the resolved workspace root, its mode,
and the active scope before the results, so it is never ambiguous which file is
being read. --json prints the entries as a bare array with no header, and an
empty result is [].`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			anchor, err := internal.ResolveSpacesAnchor()
			if err != nil {
				return err
			}

			cwd, _ := os.Getwd()
			result, err := internal.SpaceList(anchor, internal.SpaceListOptions{
				Feature: feature,
				All:     all,
				Kind:    kind,
				Cwd:     cwd,
			})
			if err != nil {
				return err
			}
			views := result.Views
			if views == nil {
				views = []internal.SpaceView{}
			}

			if jsonOutput {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				return enc.Encode(views)
			}

			_, _ = fmt.Fprintf(cmd.OutOrStdout(), "Workspace: %s (mode: %s, scope: %s)\n\n",
				anchor.Root, anchor.Mode, result.Scope())

			if len(views) == 0 {
				if result.Total == 0 {
					_, _ = fmt.Fprintln(cmd.OutOrStdout(),
						"No spaces registered. Use 'tws space add <name> <path> --kind <kind>' to add one.")
					return nil
				}
				_, _ = fmt.Fprintf(cmd.OutOrStdout(),
					"No spaces match the active filters (%d registered). Use 'tws space list --all' to see every entry.\n",
					result.Total)
				return nil
			}

			nameWidth, kindWidth := 0, 0
			for _, v := range views {
				if len(v.Name) > nameWidth {
					nameWidth = len(v.Name)
				}
				if len(v.Kind) > kindWidth {
					kindWidth = len(v.Kind)
				}
			}

			for _, v := range views {
				line := fmt.Sprintf("%-*s  %-*s  %s", nameWidth, v.Name, kindWidth, v.Kind, v.ResolvedPath)
				if v.Status != internal.SpaceStatusOK {
					line += fmt.Sprintf("  (%s)", v.Status)
				}
				if v.Feature != "" {
					line += fmt.Sprintf("  (feature: %s)", v.Feature)
				}
				if v.ScopeStatus == internal.SpaceScopeStatusFeatureMissing {
					line += "  (feature missing)"
				}
				_, _ = fmt.Fprintln(cmd.OutOrStdout(), line)
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&feature, "feature", "", "Show workspace-wide entries plus this feature's entries")
	cmd.Flags().BoolVar(&all, "all", false, "Show every entry regardless of scope")
	cmd.Flags().StringVar(&kind, "kind", "", "Filter by kind")
	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
	cmd.MarkFlagsMutuallyExclusive("all", "feature")
	registerSpaceScopeCompletions(cmd)
	_ = cmd.RegisterFlagCompletionFunc("kind",
		func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			return internal.SpaceConventionalKinds, cobra.ShellCompDirectiveNoFileComp
		})

	return cmd
}

func spaceShowCmd() *cobra.Command {
	var feature string
	var workspace bool
	var jsonOutput bool

	cmd := &cobra.Command{
		Use:   "show <name>",
		Short: "Show one registered sibling space",
		Long: `Show one registered sibling space.

A bare name resolves the unique entry with that name. When the same name exists
both workspace-wide and inside a feature, select the one you mean with
--workspace or --feature <name>.`,
		Args:              cobra.ExactArgs(1),
		ValidArgsFunction: completeSpaceNames,
		RunE: func(cmd *cobra.Command, args []string) error {
			anchor, err := internal.ResolveSpacesAnchor()
			if err != nil {
				return err
			}

			selector, err := internal.NewSpaceSelector(args[0], feature, workspace)
			if err != nil {
				return err
			}
			view, err := internal.SpaceShow(anchor, selector)
			if err != nil {
				return err
			}

			if jsonOutput {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				return enc.Encode(view)
			}

			out := cmd.OutOrStdout()
			_, _ = fmt.Fprintf(out, "Name:        %s\n", view.Name)
			_, _ = fmt.Fprintf(out, "Kind:        %s\n", view.Kind)
			scope := "workspace"
			if view.Scope == internal.SpaceScopeFeature {
				scope = "feature " + view.Feature
				if view.ScopeStatus == internal.SpaceScopeStatusFeatureMissing {
					scope += " (missing)"
				}
			}
			_, _ = fmt.Fprintf(out, "Scope:       %s\n", scope)
			_, _ = fmt.Fprintf(out, "Path:        %s\n", view.Path)
			_, _ = fmt.Fprintf(out, "Resolved:    %s\n", view.ResolvedPath)
			_, _ = fmt.Fprintf(out, "Status:      %s\n", view.Status)
			if view.Description != "" {
				_, _ = fmt.Fprintf(out, "Description: %s\n", view.Description)
			}
			_, _ = fmt.Fprintf(out, "Added:       %s\n", view.AddedAt.Format("2006-01-02 15:04:05"))
			if view.UpdatedAt != nil {
				_, _ = fmt.Fprintf(out, "Updated:     %s\n", view.UpdatedAt.Format("2006-01-02 15:04:05"))
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&feature, "feature", "", "Restrict to a feature scope")
	cmd.Flags().BoolVar(&workspace, "workspace", false, "Restrict to the workspace-wide scope")
	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
	cmd.MarkFlagsMutuallyExclusive("feature", "workspace")
	registerSpaceScopeCompletions(cmd)

	return cmd
}

