	}

	tickets := mustMkdir(t, filepath.Join(root, "tickets"))
	initSiblingRepo(t, tickets)
	nested := mustMkdir(t, filepath.Join(tickets, "store"))

	if _, err := runSpace(t, "add", "tickets", tickets, "--kind", "tickets"); err != nil {
