func TestSpaceShowRemoveScopeSelectors(t *testing.T) {
	repo := setupGitRepo(t, "master")
	withUnifiedWorkspaceEnv(t, repo)
	root := internal.TwsRoot()

	if err := addExternal("acme", nil, "", "", false, false, false); err != nil {
