package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func syncCmd() *cobra.Command {
	var verbose bool
	var push bool
	var cont bool
	var abort bool
	var testCmd string

	cmd := &cobra.Command{
		Use:   "sync <feature>",
		Short: "Rebase branches in dependency order",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return runCheckoutSync(args[0], push, testCmd, cont, abort, verbose)
			}

			feature := args[0]
			// One guard covers the plain, --abort, and --continue paths.
			// syncFeature carries none: it has no error channel and would
			// degrade the message to "sync incomplete".
			if err := internal.GuardFeatureName(internal.TwsRoot(), feature); err != nil {
				return err
			}
			featurePath, fpErr := ws.ResolveFeaturePath(feature)
			if fpErr != nil {
				return fpErr
			}

			if abort {
				return handleSyncAbort(feature, featurePath)
			}
			if cont {
				return handleSyncContinue(feature, featurePath, push)
			}
			if internal.HasSyncState(featurePath) {
				state, _ := internal.LoadSyncState(featurePath)
				return fmt.Errorf("previous sync incomplete (failed on: %s); use --continue or --abort", state.FailedBranch)
			}

			result := syncFeature(feature, verbose)
			if !result.Complete {
				return fmt.Errorf("sync incomplete")
			}
			fmt.Println("Sync complete.")
			if push {
				fmt.Println("\nPushing...")
				if err := pushFeature(feature, false); err != nil {
					return err
				}
			}
			return nil
		},
	}

	cmd.Flags().BoolVarP(&verbose, "verbose", "v", false, "Show full git fetch output")
	cmd.Flags().BoolVar(&push, "push", false, "Push all branches after syncing")
	cmd.Flags().BoolVar(&cont, "continue", false, "Resume after conflict resolution")
	cmd.Flags().BoolVar(&abort, "abort", false, "Discard sync state and start fresh")
	cmd.Flags().StringVar(&testCmd, "test", "", "Validation command to run after each rebase (checkout mode)")

	return cmd
}

func handleSyncAbort(feature, featurePath string) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		fmt.Println("Nothing to abort — no sync in progress.")
		return nil
	}
	if state.FailedBranch != "" {
		path := internal.WorktreePath(feature, state.FailedBranch)
		if isRebaseInProgress(path) {
			_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
		}
	}
	internal.DeleteSyncState(featurePath)
	fmt.Println("Sync state cleared.")
	return nil
}

func handleSyncContinue(feature, featurePath string, push bool) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	failedPath := internal.WorktreePath(feature, state.FailedBranch)
	if state.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", state.FailedBranch)
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	if state.FailedBranch != "" {
		failedEntry := internal.GetBranch(stack, state.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", state.FailedBranch)
		}
		if !branchContainsConfiguredParent(feature, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(state.FailedBranch, "active", "resolved"))
	}

	done := make(map[string]bool)
	for _, name := range state.Completed {
		done[name] = true
	}
	if state.FailedBranch != "" {
		done[state.FailedBranch] = true
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		return err
	}
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(state.Pending))
	result := syncWithStackFiltered(feature, featurePath, stack, sorted, done)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		fmt.Println("\nPushing...")
		if err := pushFeature(feature, false); err != nil {
			return err
		}
	}
	return nil
}

func branchContainsConfiguredParent(feature string, stack internal.Stack, child internal.StackEntry) bool {
	parent := internal.GetBranch(stack, child.Base)
	if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
		return true
	}
	path := internal.WorktreePath(feature, child.Name)
	return internal.RunSilentDir(path, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) == nil
}

func isRebaseInProgress(worktreePath string) bool {
	// Check for .git/rebase-merge or .git/rebase-apply
	gitDir := internal.RunSilent("git", "-C", worktreePath, "rev-parse", "--git-dir")
	if gitDir != nil {
		return false
	}
	// Simpler: check if git status shows rebase
	err := internal.RunSilent("git", "-C", worktreePath, "rebase", "--show-current-patch")
	return err == nil
}

func syncFeature(feature string, verbose bool) syncResult {
	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		fetchQuiet("", "", verbose)
		syncFallback(featurePath)
		return syncResult{Complete: true}
	}

	repos := internal.UniqueRepos(stack, featurePath)
	for repo, wtPath := range repos {
		fetchQuiet(repo, wtPath, verbose)
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncWithStack(feature, featurePath, stack, sorted)
}

func fetchQuiet(repo, wtPath string, verbose bool) {
	label := "default repo"
	if repo != "" {
		label = repo
	}

	if verbose {
		fmt.Printf("Fetching %s...\n", label)
		if wtPath != "" {
			_ = internal.RunDir(wtPath, "git", "fetch")
		} else if repo != "" {
			_ = internal.RunDir(repo, "git", "fetch")
		} else {
			_ = internal.Run("git", "fetch")
		}
	} else {
		fmt.Printf("Fetching %s... ", label)
		var err error
		if wtPath != "" {
			err = internal.RunSilentDir(wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunSilentDir(repo, "git", "fetch")
		} else {
			err = internal.RunSilent("git", "fetch")
		}
		if err != nil {
			fmt.Println("failed")
		} else {
			fmt.Println("done")
		}
	}
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func templateCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "template",
		Short: "Manage workspace templates",
	}

	cmd.AddCommand(templateSyncCmd())

	return cmd
}

func templateSyncCmd() *cobra.Command {
	var templates []string
	var all bool

	cmd := &cobra.Command{
		Use:   "sync [feature]",
		Short: "Apply template files to existing feature(s)",
		Long:  "Copy template files into a feature's inject/ directory. Skips existing files. Use --all to sync all features.",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if all {
				features, listErr := internal.ListFeaturesE()
				if listErr != nil {
					return listErr
				}
				if len(features) == 0 {
					fmt.Println("No features found.")
					return nil
				}
				for _, feature := range features {
					syncFeatureTemplate(feature, templates)
				}
				return nil
			}

			if len(args) == 0 {
				return fmt.Errorf("usage: tws template sync <feature> [--template <dir>]\n       tws template sync --all")
			}

			// syncFeatureTemplate has no error channel and prints to stdout,
			// so a registered-space conflict or untrusted spaces metadata must
			// be reported here to exit nonzero. A failing RequireWorkspace is
			// deliberately not promoted: it falls through to the legacy shape.
			if ws, wsErr := internal.RequireWorkspace(); wsErr == nil {
				if err := internal.GuardFeatureName(ws.MetadataRoot, args[0]); err != nil {
					return err
				}
			}

			syncFeatureTemplate(args[0], templates)
			return nil
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Template directory (can be specified multiple times)")
	cmd.Flags().BoolVar(&all, "all", false, "Sync all features")

	return cmd
}

func syncFeatureTemplate(feature string, extraTemplates []string) {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		fmt.Printf("%s: %v\n", feature, err)
		return
	}

	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		fmt.Printf("%s: error creating inject dir: %v\n", feature, err)
		return
	}

	fmt.Printf("%s:\n", feature)
	applyTemplates(injectDir, extraTemplates)

	// Re-sync inject into worktrees
	target := internal.ResolveInjectInto("")
	count, err := internal.InjectFilesForFeature(featurePath, target)
	if err != nil {
		fmt.Printf("  Warning: worktree inject failed: %v\n", err)
	} else if count > 0 {
		fmt.Printf("  Synced inject to %d worktree(s)\n", count)
	}
}

package internal

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

// MigrateResult describes the outcome of a migration run.
type MigrateResult struct {
	Migrated []string // features successfully moved
	Skipped  []string // features already in new layout
	Errors   []string // rollback/failure messages
}

// MigrateFeatureLayout migrates a single feature from legacy (.tws/<name>)
// to new layout (.tws/features/<name>). Returns an error if:
//   - feature name is invalid/unsafe
//   - the name or the directory is claimed by a registered sibling space
//   - source is a symlink
//   - destination already exists (collision)
//   - move fails
func MigrateFeatureLayout(ws Workspace, feature string) (err error) {
	if err := validateFeatureName(feature); err != nil {
		return err
	}

	src := filepath.Join(ws.MetadataRoot, feature)
	dst := filepath.Join(ws.MetadataRoot, "features", feature)

	// Refuse to move a directory whose name is owned by a registered sibling
	// space, or that still contains a registered target, before any
	// filesystem work. The transaction also refuses a destination name owned
	// by a features/<name> space, which the collision check below cannot see,
	// and it holds the spaces lock across os.Rename so no concurrent
	// `tws space add` can register into the directory being moved.
	tx, err := BeginSpacesLayoutMigration(ws.MetadataRoot,
		[]LayoutMigrationTarget{{Feature: feature, Path: src}})
	if err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, tx.Release())
	}()

	// Reject symlinks at source.
	info, statErr := os.Lstat(src)
	if statErr != nil {
		return fmt.Errorf("source %s does not exist: %w", src, statErr)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("source %s is a symlink; refusing to migrate", src)
	}
	if !info.IsDir() {
		return fmt.Errorf("source %s is not a directory", src)
	}

	// Check destination collision.
	if _, dstErr := os.Lstat(dst); dstErr == nil {
		return fmt.Errorf("destination %s already exists (collision)", dst)
	}

	// Ensure features/ parent exists.
	if mkErr := os.MkdirAll(filepath.Dir(dst), 0755); mkErr != nil {
		return fmt.Errorf("creating features dir: %w", mkErr)
	}

	return os.Rename(src, dst)
}

// MigrateAllFeatures migrates all legacy features to the new layout.
// Preflight: one spaces transaction for the whole batch, then all sources and
// destinations, before moving any.
// On failure mid-run: best-effort rollback of previously moved features.
func MigrateAllFeatures(ws Workspace) (result MigrateResult) {
	if ws.Mode != ModeCheckout {
		result.Errors = append(result.Errors, "migrate-layout requires checkout mode")
		return result
	}

	// Discover legacy candidates (dirs in MetadataRoot that are not reserved).
	// Discovery is read-only, so it may precede the spaces preflight; nothing
	// is created or moved until the whole batch has been cleared.
	entries, err := os.ReadDir(ws.MetadataRoot)
	if err != nil {
		result.Errors = append(result.Errors, fmt.Sprintf("reading %s: %v", ws.MetadataRoot, err))
		return result
	}

	var candidates []string
	for _, e := range entries {
		if !e.IsDir() || isReservedDir(e.Name()) {
			continue
		}
		candidates = append(candidates, e.Name())
	}
	sort.Strings(candidates)

	// Fail-closed spaces preflight, executed exactly once for the whole batch
	// and always before `features/` is created or anything is moved. A
	// registered name, or a registered target inside any candidate, is an
	// error and never a skip: one registration blocks every candidate rather
	// than producing a partial run.
	targets := make([]LayoutMigrationTarget, 0, len(candidates))
	for _, name := range candidates {
		targets = append(targets, LayoutMigrationTarget{
			Feature: name,
			Path:    filepath.Join(ws.MetadataRoot, name),
		})
	}
	tx, txErr := BeginSpacesLayoutMigration(ws.MetadataRoot, targets)
	if txErr != nil {
		result.Errors = append(result.Errors, txErr.Error())
		return result
	}
	// The lock is held across every move and any rollback below.
	defer func() {
		if relErr := tx.Release(); relErr != nil {
			result.Errors = append(result.Errors, relErr.Error())
		}
	}()

	if len(candidates) == 0 {
		return result
	}

	// --- Preflight: check all sources and destinations ---
	type migration struct {
		name string
		src  string
		dst  string
	}
	var migrations []migration

	for _, name := range candidates {
		src := filepath.Join(ws.MetadataRoot, name)
		dst := filepath.Join(ws.MetadataRoot, "features", name)

		// Reject symlinks.
		info, err := os.Lstat(src)
		if err != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("stat %s: %v", src, err))
			continue
		}
		if info.Mode()&os.ModeSymlink != 0 {
			result.Errors = append(result.Errors, fmt.Sprintf("%s is a symlink; skipped", src))
			continue
		}

		// Check if already migrated (exists under features/).
		if _, err := os.Lstat(dst); err == nil {
			result.Skipped = append(result.Skipped, name)
			continue
		}

		migrations = append(migrations, migration{name: name, src: src, dst: dst})
	}

	// If any preflight errors detected, abort without moving anything.
	if len(result.Errors) > 0 {
		return result
	}

	// Ensure features/ exists.
	featuresDir := filepath.Join(ws.MetadataRoot, "features")
	if err := os.MkdirAll(featuresDir, 0755); err != nil {
		result.Errors = append(result.Errors, fmt.Sprintf("creating features dir: %v", err))
		return result
	}

	// --- Execute moves with rollback on failure ---
	var moved []migration
	for _, m := range migrations {
		if err := os.Rename(m.src, m.dst); err != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("moving %s: %v", m.name, err))
			// Best-effort rollback.
			for _, done := range moved {
				if rbErr := os.Rename(done.dst, done.src); rbErr != nil {
					result.Errors = append(result.Errors, fmt.Sprintf("rollback %s failed: %v", done.name, rbErr))
				}
			}
			return result
		}
		moved = append(moved, m)
		result.Migrated = append(result.Migrated, m.name)
	}

	return result
}

package internal

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func makeTestDir(t *testing.T, path string) {
	t.Helper()
	if err := os.MkdirAll(path, 0755); err != nil {
		t.Fatal(err)
	}
}

func makeTestSymlink(t *testing.T, target, link string) {
	t.Helper()
	if err := os.Symlink(target, link); err != nil {
		t.Fatal(err)
	}
}

func TestMigrateFeatureLayout_Single(t *testing.T) {
	dir := t.TempDir()
	ws := Workspace{MetadataRoot: dir, Mode: ModeCheckout}

	// Create legacy feature.
	makeTestDir(t, filepath.Join(dir, "myfeat", "worktrees"))
	makeTestDir(t, filepath.Join(dir, "features"))

	if err := MigrateFeatureLayout(ws, "myfeat"); err != nil {
		t.Fatal(err)
	}

	// Verify moved.
	if _, err := os.Stat(filepath.Join(dir, "features", "myfeat", "worktrees")); err != nil {
		t.Error("feature not at new location")
	}
	if _, err := os.Stat(filepath.Join(dir, "myfeat")); err == nil {
		t.Error("legacy location should not exist")
	}
}

func TestMigrateFeatureLayout_CollisionRejected(t *testing.T) {
	dir := t.TempDir()
	ws := Workspace{MetadataRoot: dir, Mode: ModeCheckout}

	makeTestDir(t, filepath.Join(dir, "feat"))
	makeTestDir(t, filepath.Join(dir, "features", "feat"))

	err := MigrateFeatureLayout(ws, "feat")
	if err == nil {
		t.Fatal("expected collision error")
	}
	if !strings.Contains(err.Error(), "collision") {
		t.Errorf("expected collision in error, got: %v", err)
	}
}

