		t.Fatal(err)
	}
	if _, _, err := SpaceAdd(anchor, SpaceAddRequest{Name: "learning", Path: filepath.Join(featureDir, "learning"), Kind: "learning"}); err != nil {
		t.Fatal(err)
	}
	if _, _, err := SpaceAdd(anchor, SpaceAddRequest{
