	if err == nil {
		t.Fatal("expected refusal")
	}
	msg := err.Error()
	for _, want := range []string{
		`cannot delete feature "acme"`, "2 registered spaces live inside",
		"learning (workspace)", "patching (feature acme)", "tws space remove",
	} {
